import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.map.js";
/* eslint-disable */
import EditFieldProperties from "@/components/FlowDesigneComponents/EditFieldProperties.vue";
import { update_expense_forms } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
// import { update_audit_logs } from "@/mixins/AuditLogActions.js";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
export default {
  props: {
    addedFlowSteps: Array,
    tableData: Object,
    templete: Array,
    workflowType: {
      type: String,
      default: 'expense',
      validator: function (value) {
        return ['expense', 'petty_cash_request', 'petty_cash_log', 'petty_cash_refill_vault'].indexOf(value) !== -1;
      }
    }
  },
  components: {
    EditFieldProperties
  },
  // mixins: [update_audit_logs],
  mixins: [get_all_org_users],
  data() {
    return {
      stepHeaders: [{
        title: "Form Field",
        align: "start",
        sortable: false,
        key: "display_label"
      }, {
        title: "Visible",
        align: "start",
        sortable: false,
        key: "is_displayed"
      }, {
        title: "Editable",
        align: "start",
        sortable: false,
        key: "is_editable"
      }, {
        title: "Mandatory",
        align: "start",
        sortable: false,
        key: "is_required"
      }],
      componentCheck: 0,
      fieldsData: [],
      stepName: "",
      stepIndex: 0,
      editformFields: false,
      flowDesignerSteps: [],
      currentSelectedFlow: [],
      loading: false,
      summaryField1: "",
      summaryField2: "",
      sumarrayItems: [],
      selectTeam: "",
      userArray: [],
      searchF: ""
    };
  },
  async created() {
    // Get the appropriate localStorage key based on workflow type
    const localStorageKey = this.getLocalStorageKey();
    var data2 = JSON.parse(localStorage.getItem(localStorageKey));
    // console.log(data2);
    this.flowDesignerSteps = data2;
    this.currentSelectedFlow = data2;
    this.summaryField1 = this.tableData.summary_field_1 == undefined ? "" : this.tableData.summary_field_1;
    this.summaryField2 = this.tableData.summary_field_2 == undefined ? "" : this.tableData.summary_field_2;
    this.selectTeam = this.tableData.notifications == undefined ? [] : this.tableData.notifications;
    await this.fetch_summary_fields();
    await this.get_all_org_users();
    this.fetch_user();
  },
  methods: {
    getLocalStorageKey() {
      switch (this.workflowType) {
        case 'expense':
          return 'flowSteps1Info';
        case 'petty_cash_request':
          return 'pettyCashRequestFlowSteps';
        case 'petty_cash_log':
          return 'pettyCashLogFlowSteps';
        case 'petty_cash_refill_vault':
          return 'pettyCashOrgFlowSteps';
        default:
          return 'flowSteps1Info';
      }
    },
    getMutationName() {
      switch (this.workflowType) {
        case 'expense':
          return 'update_expense_forms';
        case 'petty_cash_request':
        case 'petty_cash_log':
        case 'petty_cash_refill_vault':
          // For now, we'll use update_expense_forms as a fallback
          // You may need to create specific mutations for petty cash workflows
          return 'update_expense_forms';
        default:
          return 'update_expense_forms';
      }
    },
    fetch_user() {
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE" && element.user_type != "CHATBOT") {
          this.userArray.push({
            title: element.full_user_name,
            user_id: element.user_email_id
          });
        }
      });
    },
    fetch_summary_fields() {
      var data = this.templete;
      this.sumarrayItems = [];
      data.forEach(element => {
        if (element.data_type != "media") {
          this.sumarrayItems.push({
            title: element.display_label,
            value: this.fetch_keys(element)
          });
        }
      });
    },
    fetch_keys(value) {
      var data = "";
      if (value.input_value == "list_users") {
        data = "user_id_text";
      } else if (value.input_value == "expense_details") {
        data = "category_id_text";
      } else if (value.input_value == "list_expense_group") {
        data = "expense_group_id_text";
      } else {
        data = value.key.toLowerCase().replace(/ /g, "_");
      }
      return data;
    },
    edit_field_properties(Step, formfieldsArry, index) {
      this.fieldsData = [];
      this.componentCheck = 1;
      this.editformFields = true;
      this.fieldsData = formfieldsArry;
      this.stepName = Step;
      this.stepIndex = index;
    },
    save_updated_changes(value, name, index) {
      if (name == this.stepName && index == this.stepIndex) {
        for (var j = 0; j < this.currentSelectedFlow[index].workflow_template.length; j++) {
          for (var k = 0; k < value.length; k++) {
            if (this.currentSelectedFlow[index].workflow_template[j].display_label == value[k].label) {
              this.currentSelectedFlow[index].workflow_template[j].is_displayed = value[k].visible;
              this.currentSelectedFlow[index].workflow_template[j].is_editable = value[k].editable;
              this.currentSelectedFlow[index].workflow_template[j].is_required = value[k].mandatory;
            }
          }
        }
      }
      this.editformFields = false;
    },
    previous_step() {
      this.$emit("backAction", this.flowDesignerSteps);
    },
    save_next_step() {
      let transformedArray = this.flowDesignerSteps.map((item, index) => {
        return {
          ...item,
          step_no: index + 1
        };
      });
      this.save_workflow_configuration(transformedArray);
      this.$emit("configuredSteps", this.flowDesignerSteps);
    },
    async save_workflow_configuration(value) {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result;

        // Handle different workflow types
        if (this.workflowType === 'expense') {
          // Use the existing update_expense_forms mutation
          result = await API.graphql(graphqlOperation(update_expense_forms, {
            input: {
              user_email_id: data.user.user_email_id,
              workflow_id: this.tableData.workflow_id,
              workflow_approval_steps: JSON.stringify(value),
              summary_field_1: this.summaryField1,
              summary_field_2: this.summaryField2,
              notifications: this.selectTeam
            }
          }));
          var response = JSON.parse(result.data.update_expense_forms);
        } else if (this.workflowType === 'petty_cash_request' || this.workflowType === 'petty_cash_log') {
          // For petty cash workflows, we'll use update_expense_forms as a fallback
          // You may need to create specific mutations for petty cash workflows
          result = await API.graphql(graphqlOperation(update_expense_forms, {
            input: {
              user_email_id: data.user.user_email_id,
              workflow_id: this.tableData.workflow_id,
              workflow_approval_steps: JSON.stringify(value),
              summary_field_1: this.summaryField1,
              summary_field_2: this.summaryField2,
              notifications: this.selectTeam
            }
          }));
          var response = JSON.parse(result.data.update_expense_forms);
        } else if (this.workflowType === 'petty_cash_refill_vault') {
          // For petty cash workflows, we'll use update_expense_forms as a fallback
          // You may need to create specific mutations for petty cash workflows
          result = await API.graphql(graphqlOperation(update_expense_forms, {
            input: {
              user_email_id: data.user.user_email_id,
              workflow_id: this.tableData.workflow_id,
              workflow_approval_steps: JSON.stringify(value),
              summary_field_1: this.summaryField1,
              summary_field_2: this.summaryField2,
              notifications: this.selectTeam
            }
          }));
          var response = JSON.parse(result.data.update_expense_forms);
        } else {
          throw new Error(`Unsupported workflow type: ${this.workflowType}`);
        }
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          await this.fetch_audit_message();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        let errorMessage = "An error occurred while saving";
        try {
          if (error && typeof error === "object") {
            if (error.errors && Array.isArray(error.errors) && error.errors.length > 0 && error.errors[0].message) {
              errorMessage = error.errors[0].message;
            } else if (error.message) {
              errorMessage = error.message;
            } else if (error.toString) {
              errorMessage = error.toString();
            }
          } else if (typeof error === "string") {
            errorMessage = error;
          }
        } catch (parseError) {
          errorMessage = "An error occurred while saving";
        }
        this.$emit("errorMsg", errorMessage);
      }
    },
    async fetch_audit_message() {
      var data = this.$store.getters.GetUserObj;
      let auditType, auditAction, auditMessage;
      switch (this.workflowType) {
        case 'expense':
          auditType = "EXPENSE_ACTION";
          auditAction = "EXPENSE_APPROVAL";
          auditMessage = `${data.user.full_user_name} Updated Expense Approval`;
          break;
        case 'petty_cash_request':
          auditType = "PETTY_CASH_ACTION";
          auditAction = "PETTY_CASH_REQUEST_APPROVAL";
          auditMessage = `${data.user.full_user_name} Updated Petty Cash Request Approval`;
          break;
        case 'petty_cash_log':
          auditType = "PETTY_CASH_ACTION";
          auditAction = "PETTY_CASH_LOG_APPROVAL";
          auditMessage = `${data.user.full_user_name} Updated Petty Cash Log Approval`;
          break;
        case 'petty_cash_refill_vault':
          auditType = "PETTY_CASH_ACTION";
          auditAction = "PETTY_CASH_REFILL_VAULT_APPROVAL";
          auditMessage = `${data.user.full_user_name} Updated Petty Cash Refill Vault Approval`;
          break;
        default:
          auditType = "EXPENSE_ACTION";
          auditAction = "EXPENSE_APPROVAL";
          auditMessage = `${data.user.full_user_name} Updated Workflow Approval`;
      }
      var auditData = {
        AuditType: auditType,
        AuditAction: auditAction,
        AuditMessage: auditMessage
      };
      this.$store.commit("SetAuditActions", auditData);
      // this.update_audit_logs();
    }
  }
};
